"""
ReazonSpeech K2 (sherpa-onnx Zipformer) ASR with native subword timestamps.

Official models only handle ~30s clips reliably — long media is windowed.
"""

from __future__ import annotations

import logging
import re
import shutil
import tempfile
import threading
from pathlib import Path
from typing import Any, Callable

import numpy as np

from ..download import is_model_installed, model_local_path
from ..progress import asr_local_from_timeline, format_mmss

ProgressCb = Callable[[dict[str, Any]], None]
CueCb = Callable[[dict[str, Any]], None]
_log = logging.getLogger("transub_engine.asr.reazon_k2")

_MODEL_CACHE: dict[str, Any] = {}
_MODEL_LOCK = threading.Lock()

_SAMPLE_RATE = 16000
_WINDOW_S = 25.0
_OVERLAP_S = 0.5
_PAD_S = 0.5
_GAP_BREAK_S = 0.45
_MAX_CUE_S = 6.5
_SENTENCE_END = set("。！？!?．.｡")

_ENCODER_CANDIDATES = (
    "encoder-epoch-99-avg-1.onnx",
    "encoder-epoch-99-avg-1.int8.onnx",
)
_DECODER_FP32 = "decoder-epoch-99-avg-1.onnx"
_DECODER_INT8 = "decoder-epoch-99-avg-1.int8.onnx"
_JOINER_FP32 = "joiner-epoch-99-avg-1.onnx"
_JOINER_INT8 = "joiner-epoch-99-avg-1.int8.onnx"


def clear_model_cache() -> int:
    with _MODEL_LOCK:
        n = len(_MODEL_CACHE)
        _MODEL_CACHE.clear()
    try:
        import gc

        gc.collect()
    except Exception:
        pass
    return n


def _resolve_onnx_triplet(model_dir: Path) -> tuple[Path, Path, Path, Path]:
    tokens = model_dir / "tokens.txt"
    if not tokens.is_file():
        raise RuntimeError(f"ReazonSpeech K2 missing tokens.txt under {model_dir}")
    enc: Path | None = None
    for name in _ENCODER_CANDIDATES:
        p = model_dir / name
        if p.is_file():
            enc = p
            break
    if enc is None:
        raise RuntimeError(f"ReazonSpeech K2 missing encoder onnx under {model_dir}")
    use_int8 = "int8" in enc.name
    dec = model_dir / (_DECODER_INT8 if use_int8 else _DECODER_FP32)
    joiner = model_dir / (_JOINER_INT8 if use_int8 else _JOINER_FP32)
    # int8-fp32 hybrid: encoder/joiner int8, decoder fp32
    if use_int8 and not dec.is_file() and (model_dir / _DECODER_FP32).is_file():
        dec = model_dir / _DECODER_FP32
    if not dec.is_file() or not joiner.is_file():
        raise RuntimeError(f"ReazonSpeech K2 incomplete onnx set under {model_dir}")
    return tokens, enc, dec, joiner


def _provider_for_device(device: str) -> str:
    d = str(device or "auto").strip().lower()
    if d in ("cpu", "coreml"):
        return d
    if d == "cuda":
        return "cuda"
    # auto: prefer CUDA when torch sees a GPU (sherpa may still fall back).
    try:
        import torch

        if torch.cuda.is_available():
            return "cuda"
    except Exception:
        pass
    return "cpu"


def _get_recognizer(model_dir: Path, device: str) -> Any:
    import sherpa_onnx

    provider = _provider_for_device(device)
    key = f"{model_dir}|{provider}"
    with _MODEL_LOCK:
        cached = _MODEL_CACHE.get(key)
        if cached is not None:
            return cached
        tokens, enc, dec, joiner = _resolve_onnx_triplet(model_dir)

        def _load(prov: str) -> Any:
            return sherpa_onnx.OfflineRecognizer.from_transducer(
                tokens=str(tokens),
                encoder=str(enc),
                decoder=str(dec),
                joiner=str(joiner),
                num_threads=2,
                sample_rate=_SAMPLE_RATE,
                feature_dim=80,
                decoding_method="greedy_search",
                provider=prov,
            )

        try:
            model = _load(provider)
        except Exception as err:
            if provider != "cpu":
                _log.warning(
                    "Reazon K2 provider=%s failed (%s); falling back to cpu",
                    provider,
                    err,
                )
                model = _load("cpu")
                provider = "cpu"
                key = f"{model_dir}|{provider}"
            else:
                raise
        _MODEL_CACHE[key] = model
        return model


def _load_mono_16k(path: str) -> np.ndarray:
    import librosa

    wav, _sr = librosa.load(path, sr=_SAMPLE_RATE, mono=True)
    return np.asarray(wav, dtype=np.float32)


def _probe_duration_s(media_path: str) -> float:
    """Probe duration without decoding the full media into RAM."""
    try:
        from .whisper_fw import _probe_duration_s as probe

        return float(probe(media_path) or 0)
    except Exception:
        return 0.0


def _windows(duration_s: float) -> list[tuple[float, float]]:
    if duration_s <= _WINDOW_S + 1.0:
        return [(0.0, max(duration_s, 0.1))]
    out: list[tuple[float, float]] = []
    cursor = 0.0
    step = max(5.0, _WINDOW_S - _OVERLAP_S)
    while cursor < duration_s - 0.05:
        end = min(duration_s, cursor + _WINDOW_S)
        out.append((cursor, end))
        if end >= duration_s - 0.05:
            break
        cursor += step
    return out or [(0.0, max(duration_s, 0.1))]


def _subwords_to_cues(
    tokens: list[str],
    timestamps: list[float],
    *,
    offset_s: float = 0.0,
) -> list[dict[str, Any]]:
    if not tokens:
        return []
    # Drop leading pad silence bias from official PAD_SECONDS ≈ 0.5–0.9.
    items = [
        (float(ts) + float(offset_s), str(tok))
        for ts, tok in zip(timestamps, tokens)
        if str(tok).strip()
    ]
    if not items:
        return []
    cues: list[dict[str, Any]] = []
    buf_toks: list[str] = []
    buf_start = items[0][0]
    prev_t = items[0][0]
    for t, tok in items:
        gap = t - prev_t
        flush = False
        if buf_toks and gap >= _GAP_BREAK_S:
            flush = True
        if buf_toks and any(ch in _SENTENCE_END for ch in buf_toks[-1]):
            flush = True
        text_so_far = "".join(buf_toks)
        if buf_toks and len(text_so_far) >= 28:
            flush = True
        if flush:
            end = max(buf_start + 0.2, prev_t + 0.12)
            cues.append(
                {
                    "start": buf_start,
                    "end": min(end, buf_start + _MAX_CUE_S),
                    "text": text_so_far.strip(),
                }
            )
            buf_toks = []
            buf_start = t
        buf_toks.append(tok)
        prev_t = t
    if buf_toks:
        text = "".join(buf_toks).strip()
        if text:
            cues.append(
                {
                    "start": buf_start,
                    "end": min(max(buf_start + 0.2, prev_t + 0.25), buf_start + _MAX_CUE_S),
                    "text": text,
                }
            )
    return cues


def _decode_waveform(model: Any, waveform: np.ndarray) -> list[dict[str, Any]]:
    if waveform.size == 0:
        return []
    # Light edge pad like upstream (helps first/last phones).
    pad = int(_PAD_S * _SAMPLE_RATE)
    if pad > 0:
        waveform = np.pad(waveform, pad_width=pad, mode="constant")
    stream = model.create_stream()
    stream.accept_waveform(_SAMPLE_RATE, waveform)
    model.decode_stream(stream)
    result = stream.result
    tokens = list(getattr(result, "tokens", None) or [])
    timestamps = list(getattr(result, "timestamps", None) or [])
    # Timestamps are relative to padded audio; subtract pad.
    timestamps = [max(0.0, float(t) - _PAD_S) for t in timestamps]
    if tokens and timestamps and len(tokens) == len(timestamps):
        return _subwords_to_cues(tokens, timestamps)
    text = str(getattr(result, "text", "") or "").strip()
    if not text:
        return []
    dur = max(0.35, len(waveform) / float(_SAMPLE_RATE) - 2 * _PAD_S)
    return [{"start": 0.0, "end": min(_MAX_CUE_S, dur), "text": text}]


def reazon_k2_transcribe(
    *,
    media_path: str,
    language: str = "ja",
    asr_model: str = "reazonspeech-k2",
    device: str = "auto",
    on_progress: ProgressCb | None = None,
    on_cue: CueCb | None = None,
    should_cancel: Callable[[], bool] | None = None,
) -> list[dict[str, Any]]:
    from ..runtime_extras import ensure_extras_for_models

    ensure_extras_for_models([asr_model], force=False, on_progress=on_progress)
    if not is_model_installed(asr_model):
        raise RuntimeError(
            f"ASR model not installed: {asr_model}. Download reazonspeech-k2 first."
        )
    model_dir = model_local_path(asr_model)
    if on_progress:
        on_progress(
            {
                "stage": "model",
                "percent": 8,
                "detail": "加载 ReazonSpeech K2…",
            }
        )
    model = _get_recognizer(model_dir, device)
    duration_s = _probe_duration_s(media_path)
    if duration_s <= 0:
        raise RuntimeError(
            f"无法读取媒体时长（{media_path}），ReazonSpeech K2 不能安全开窗。"
            "请确认 ffmpeg/ffprobe 可用后重试。"
        )
    windows = _windows(duration_s)

    # Prefer ffmpeg window extracts for video containers; fall back to one full load.
    from ..audio.preprocess import trim_media_window

    work = Path(tempfile.mkdtemp(prefix="reazon_k2_"))
    all_cues: list[dict[str, Any]] = []
    full_waveform: np.ndarray | None = None
    full_load_failed = False
    try:
        for i, (start, end) in enumerate(windows):
            if should_cancel and should_cancel():
                raise RuntimeError("cancelled")
            if on_progress:
                local = asr_local_from_timeline(
                    processed_s=start,
                    duration_s=duration_s,
                    start=12.0,
                    end=92.0,
                )
                detail = f"{format_mmss(start)} / {format_mmss(duration_s)} · K2"
                on_progress(
                    {
                        "stage": "transcribe",
                        "percent": int(local),
                        "detail": detail,
                        "processedSec": float(start),
                        "mediaDurationSec": duration_s,
                    }
                )
            waveform: np.ndarray | None = None
            try:
                wav_path = trim_media_window(
                    media_path,
                    start_sec=start,
                    end_sec=end,
                    out_dir=work / f"w{i:04d}",
                )
                waveform = _load_mono_16k(str(wav_path))
            except Exception as err:
                if full_load_failed:
                    _log.warning(
                        "Reazon K2 window %s-%s skipped (trim failed, no full fallback): %s",
                        start,
                        end,
                        err,
                    )
                    continue
                if full_waveform is None:
                    try:
                        _log.warning(
                            "Reazon K2 trim failed at %.1f-%.1fs (%s); "
                            "loading full audio once for remaining windows",
                            start,
                            end,
                            err,
                        )
                        full_waveform = _load_mono_16k(media_path)
                    except Exception as err2:
                        full_load_failed = True
                        _log.warning(
                            "Reazon K2 full-audio fallback failed: %s",
                            err2,
                        )
                        continue
                i0 = int(start * _SAMPLE_RATE)
                i1 = int(end * _SAMPLE_RATE)
                waveform = full_waveform[i0:i1]
            if waveform is None or len(waveform) == 0:
                continue
            part = _decode_waveform(model, waveform)
            for cue in part:
                item = dict(cue)
                item["start"] = float(item["start"]) + start
                item["end"] = float(item["end"]) + start
                if on_cue:
                    on_cue(item)
                all_cues.append(item)
    finally:
        shutil.rmtree(work, ignore_errors=True)

    # Drop overlap duplicates (keep earlier).
    all_cues.sort(key=lambda c: (float(c.get("start") or 0), float(c.get("end") or 0)))
    cleaned: list[dict[str, Any]] = []
    for cue in all_cues:
        text = re.sub(r"\s+", "", str(cue.get("text") or "")).strip()
        if not text:
            continue
        cue = dict(cue)
        cue["text"] = str(cue.get("text") or "").strip()
        if cleaned:
            prev = cleaned[-1]
            if abs(float(cue["start"]) - float(prev["start"])) < 0.35 and text == re.sub(
                r"\s+", "", str(prev.get("text") or "")
            ):
                continue
            if float(cue["start"]) < float(prev["end"]) - 0.05:
                cue["start"] = float(prev["end"])
                if float(cue["end"]) <= float(cue["start"]):
                    cue["end"] = float(cue["start"]) + 0.25
        cleaned.append(cue)

    if on_progress:
        on_progress(
            {
                "stage": "transcribe",
                "percent": 96,
                "detail": f"{len(cleaned)} 条（ReazonSpeech K2）",
                "processedSec": duration_s if duration_s > 0 else None,
                "mediaDurationSec": duration_s if duration_s > 0 else None,
            }
        )
    return cleaned
